import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"第 1 课 我是什么：像新同事，不是魔法","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第1课 我是什么：像新同事，不是魔法.md","filePath":"easy/第1课 我是什么：像新同事，不是魔法.md"}'),d={name:"easy/第1课 我是什么：像新同事，不是魔法.md"};function l(i,t,n,h,s,_){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="第-1-课-我是什么-像新同事-不是魔法" tabindex="-1">第 1 课 我是什么：像新同事，不是魔法 <a class="header-anchor" href="#第-1-课-我是什么-像新同事-不是魔法" aria-label="Permalink to &quot;第 1 课 我是什么：像新同事，不是魔法&quot;">​</a></h1><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>把我当成一个<strong>新来的同事</strong>，坐在你电脑旁边。</p><ul><li>他不会读心术，你说什么，他就听什么；</li><li>他不会自己乱跑，你让他干活，他才干活；</li><li>他干活挺快，但偶尔也会出错，需要你检查；</li><li>你用得越久，他越懂你的习惯。</li></ul><p><strong>就这么简单。不是魔法，是一个很勤快、有点聪明、需要你带的新同事。</strong></p><h2 id="我能碰你电脑里的什么" tabindex="-1">我能碰你电脑里的什么？ <a class="header-anchor" href="#我能碰你电脑里的什么" aria-label="Permalink to &quot;我能碰你电脑里的什么？&quot;">​</a></h2><p>给你看一张&quot;权限表&quot;，比什么都清楚：</p><table tabindex="0"><thead><tr><th>我能做</th><th>比方</th><th>例子</th></tr></thead><tbody><tr><td>看和改文件</td><td>像能打开你电脑里的文档</td><td>帮你改报告、整理文件夹</td></tr><tr><td>敲命令</td><td>像有个会打字的手</td><td>帮你跑程序、批量处理</td></tr><tr><td>帮你找东西</td><td>像会翻你文件柜的人</td><td>&quot;那个文件叫啥来着？&quot;</td></tr><tr><td>记住你的偏好</td><td>像记小本本</td><td>记住你喜欢简洁、中文、Excel</td></tr><tr><td>叫帮手</td><td>像喊一帮同事来</td><td>任务大时多个人一起干</td></tr></tbody></table><h2 id="我不会什么-重要" tabindex="-1">我不会什么？（重要！） <a class="header-anchor" href="#我不会什么-重要" aria-label="Permalink to &quot;我不会什么？（重要！）&quot;">​</a></h2><ul><li>❌ 我不会读心术——你不说，我不知道；</li><li>❌ 我看不见你整个电脑——我只在你给我的&quot;工作区&quot;里干活；</li><li>❌ 我不能随便上网——除非你给链接或工具；</li><li>❌ 我不是 100% 对——重要的事，你要检查。</li></ul><h2 id="一分钟测试-你听懂了吗" tabindex="-1">一分钟测试：你听懂了吗？ <a class="header-anchor" href="#一分钟测试-你听懂了吗" aria-label="Permalink to &quot;一分钟测试：你听懂了吗？&quot;">​</a></h2><p>问自己一个问题：<strong>&quot;我是该把它当搜索引擎，还是当新同事？&quot;</strong></p><ul><li>当搜索引擎 → 你会失望（&quot;问一句，答一句，就没下文了&quot;）；</li><li>当新同事 → 你会惊喜（&quot;说清楚要啥，他真的把活干完了&quot;）。</li></ul><p>答案是：<strong>当新同事。</strong> 恭喜你，第 1 课毕业。</p><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><p>👉 [第 2 课：怎么跟我说](第2课 怎么跟我说：像点菜一样说清楚.md) —— 学会第一句&quot;人话指令&quot;。</p>',16)])])}const q=a(d,[["render",l]]);export{c as __pageData,q as default};
